import {isDraft,persisted,removeAuthored} from './drafts.mjs';
import {documentDiff,historyValue} from './history.mjs';
import {TASK_STATES,SOURCE_TYPES,sourceRecord,taskSnapshot,taskOutdated,submitTask,transitionTask} from './workflow.mjs';
import {STATES,MODES,STATE_LABEL,senseIndex,affected,eligibleExceptions,recordState,canonical,numberId,syncChanges,validate} from './engine.mjs';
let d,savedDesign,revision,token,snapshot,issues=[],stats={},dirty=false,busy=false,page='words',sub='words',selection='',grammarPage='definition',palette='pos',search='',filterGrammar='',filterState='active',offset=0,toastTimer,draftTimer;
let grammarSentence='',grammarListScroll=0,taskFilter='open',taskVersion='';
const DRAFT='puzzleapple-language-v2-draft',PAGE_SIZE=30;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=p=>(['w','s','p','G','R'].includes(p)?'draft-':'')+p+'-'+crypto.randomUUID();
const displayRef=id=>isDraft(id)?'未保存 · 保存后编号':id;
const option=(v,t,current)=>`<option value="${e(v)}" ${v===current?'selected':''}>${e(t)}</option>`;
const badge=(state,title)=>`<span class="badge ${e(state)}">${e(title||STATES[state]||state)}</span>`;
const sym=(url,size='')=>`<span class="symbol ${size} ${url?'':'blank'}" aria-label="${url?'词的符号':'未设置符号'}">${url?`<img src="${e(url)}" alt="词的符号">`:''}</span>`;
const field=(title,name,value,kind='area')=>`<label>${e(title)}${kind==='input'?`<input name="${e(name)}" value="${e(value)}">`:`<textarea name="${e(name)}" class="${kind==='long'?'long':''}">${e(value)}</textarea>`}</label>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
function modal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function persistDraft(){if(dirty)try{localStorage.setItem(DRAFT,JSON.stringify({revision,design:d,at:new Date().toISOString()}));}catch{toast('浏览器草稿空间不足，请保存到项目或导出 JSON。');}}
function changed(){dirty=true;$('#save-state').textContent='有未保存的设计';$('#save-state').classList.add('dirty');clearTimeout(draftTimer);draftTimer=setTimeout(persistDraft,500);}
function viewState(){return {page,sub,selection,grammarPage,grammarSentence,grammarListScroll,palette,search,filterGrammar,filterState,offset,taskFilter,taskVersion,scroll:window.scrollY};}
function applyView(v){({page='words',sub='words',selection='',grammarPage='definition',grammarSentence='',grammarListScroll=0,palette='pos',search='',filterGrammar='',filterState='active',offset=0,taskFilter='open',taskVersion=''}=v);}
function navigate(action){const depth=history.state?.workbench?history.state.depth:0;history.replaceState({workbench:true,depth,view:viewState()},'');action();render();window.scrollTo(0,0);history.pushState({workbench:true,depth:depth+1,view:viewState()},'', '#'+page);updateBack();}
function updateBack(){let b=$('#navigation-back');if(!b){b=document.createElement('button');b.id='navigation-back';b.className='text-link navigation-back';$('#workspace').before(b);}b.hidden=!(history.state?.depth>0);b.textContent='← 返回上一页';b.onclick=()=>history.back();}
function go(next,id=''){navigate(()=>{page=next;selection=id;grammarSentence='';search='';offset=0;});}
window.addEventListener('popstate',ev=>{if(!ev.state?.workbench)return;applyView(ev.state.view);render();requestAnimationFrame(()=>window.scrollTo(0,ev.state.view.scroll||0));});
function wordDescription(w){return w.senses.filter(s=>!s.archived).map(s=>s.text).join(' · ')||'尚无词义';}
function sentenceTitle(r){return r.tokens.map(t=>t.text).join(' · ');}
function allRows(){return Object.values(d.sentences).sort((a,b)=>a.id.localeCompare(b.id,undefined,{numeric:true}));}
function render(){
  $('#heading').textContent={words:'词库',grammar:'语法结构',sentences:'所有可能性',development:'开发进度'}[page];
  $('#nav').innerHTML=[['words','词库',d.words.filter(w=>!w.archived).length],['grammar','语法结构',d.grammars.filter(g=>!g.archived).length],['sentences','所有可能性',allRows().filter(r=>r.active).length],['development','开发进度',(d.tasks||[]).filter(t=>!t.archived&&!['passed','deferred'].includes(t.status)).length]].map(([id,t,n])=>`<button data-page="${id}" class="${page===id?'active':''}">${t}<small>${n}</small></button>`).join('');
  $$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
  if(page==='words')renderWords();if(page==='grammar')renderGrammar();if(page==='sentences')renderSentences();if(page==='development')renderDevelopment();updateBack();
}
function bindFields(container,record,after){$(container).oninput=ev=>{if(!ev.target.name)return;record[ev.target.name]=ev.target.type==='checkbox'?ev.target.checked:ev.target.value;changed();after?.(ev.target.name);};}
function archivePrompt(title,detail,action){modal(`<h2>${e(title)}</h2><p class="note">${e(detail)} 历史内容、句子编号和笔记会保留，可在已移除记录中恢复。保存后更新组合。</p><div class="actions"><button class="primary" id="archive-yes">移出当前设计并保留历史</button></div>`);$('#archive-yes').onclick=()=>{action();changed();$('#modal').close();render();};}
function removeItem(kind,id,title){
  const action=()=>{removeAuthored(d,savedDesign,kind,id);changed();};
  if(persisted(savedDesign,kind,id))return archivePrompt(title,'这是已保存的内容，删除记录将在下次保存时进入历史。',action);
  try{action();if($('#modal').open)$('#modal').close();render();toast('未保存的新增内容已移除，不占用编号、不保留删除记录。');}catch(err){toast(err.message);}
}
function renderWords(){
  $('#workspace').innerHTML=`<div class="subnav"><button data-sub="words" class="${sub==='words'?'active':''}">词条</button><button data-sub="parts" class="${sub==='parts'?'active':''}">词性管理</button><button data-sub="sync" class="${sub==='sync'?'active':''}">引擎对应 <span class="count">${syncChanges(d).length}</span></button></div><div id="word-content"></div>`;
  $$('[data-sub]').forEach(b=>b.onclick=()=>{navigate(()=>{sub=b.dataset.sub;selection='';});});
  if(sub==='parts')return renderParts();if(sub==='sync')return renderSync();
  const active=d.words.filter(w=>!w.archived);if(!active.some(w=>w.id===selection))selection=active[0]?.id||'';
  $('#word-content').innerHTML=`<div class="pagebar"><div><h2>从符号开始定义词义</h2><p>每个词可以有多个词义；每个词义选择自己的词性。没有图片时保留空白。</p></div><button id="add-word" class="primary">＋ 添加词</button></div><div class="split"><div><div class="list" id="word-list">${active.map(w=>`<button class="word-card ${selection===w.id?'active':''}" data-word="${e(w.id)}">${sym(w.symbol)}<span class="sense-list"><b>${e(wordDescription(w))}</b><small>${w.senses.filter(s=>!s.archived).length} 个词义</small></span></button>`).join('')||'<p class="empty">添加第一个词。</p>'}</div>${d.words.some(w=>w.archived)?`<details class="technical"><summary>已移除的词</summary>${d.words.filter(w=>w.archived).map(w=>`<p>${e(wordDescription(w))} <button class="tiny" data-restore-word="${e(w.id)}">恢复</button></p>`).join('')}</details>`:''}</div><div id="word-detail"></div></div>`;
  $$('[data-word]').forEach(b=>b.onclick=()=>{navigate(()=>{selection=b.dataset.word;});});
  $('#add-word').onclick=()=>{const word={id:uid('w'),code:'',symbol:'',notes:'',senses:[],archived:false,source:null};d.words.push(word);selection=word.id;changed();render();};
  $$('[data-restore-word]').forEach(b=>b.onclick=()=>{d.words.find(w=>w.id===b.dataset.restoreWord).archived=false;changed();render();});
  const w=d.words.find(w=>w.id===selection);if(!w)return;
  $('#word-detail').innerHTML=`<article class="panel"><div class="detail-head"><div><h2>词条</h2><p class="note">符号代表这个词，下面分别描述它的含义。</p></div><button class="tiny danger" id="remove-word">移除词</button></div><div class="symbol-editor">${sym(w.symbol,'big')}<div><div class="actions"><button id="upload-symbol">${w.symbol?'更换符号':'上传符号'}</button>${w.symbol?'<button id="clear-symbol">清空图片</button>':''}</div><p class="note">PNG / JPEG / WebP，最大 2 MB。<br>图片保存在设计文档中，不覆盖 Unity 原图。</p></div></div><div class="section-head"><h3>词义</h3><button id="add-sense" class="tiny">＋ 添加词义</button></div><div id="meanings">${w.senses.filter(s=>!s.archived).map(s=>`<div class="meaning" data-sense="${e(s.id)}"><div class="row">${field('这个词义是什么','text',s.text,'input')}<label>词性<select name="posId">${d.parts.filter(p=>!p.archived||p.id===s.posId).map(p=>option(p.id,p.name+(p.archived?'（已移除）':''),s.posId)).join('')}</select></label><button data-delete-sense="${e(s.id)}" class="tiny danger">移除</button></div>${field('词义说明','notes',s.notes)}</div>`).join('')||'<p class="note">先添加词义，再为它选择词性。</p>'}</div><button id="manage-parts" class="text-link">管理词性</button>${w.senses.some(s=>s.archived)?`<details class="technical"><summary>已移除的词义</summary>${w.senses.filter(s=>s.archived).map(s=>`<p>${e(s.text)} <button class="tiny" data-restore-sense="${e(s.id)}">恢复</button></p>`).join('')}</details>`:''}<div class="section fields" id="word-notes"><label class="check-label"><input type="checkbox" name="designPending" ${w.designPending?'checked':''}>待设计（给自己的提醒）</label>${field('备注','notes',w.notes,'long')}</div><details class="technical"><summary>引擎对应与稳定标识</summary><p>${e(w.source?.path||'尚未建立 SO 对应；后续开发任务会处理。')}</p><div id="word-code">${field('内部映射名称（可留空，由开发任务确定）','code',w.code,'input')}</div><p>${e(displayRef(w.id))}</p></details></article>`;
  $('#remove-word').onclick=()=>removeItem('word',w.id,'移除这个词');
  $('#upload-symbol').onclick=()=>{$('#symbol-input').value='';$('#symbol-input').click();};
  $('#symbol-input').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('图片超过 2 MB。');const result=await fetch('/api/symbol',{method:'POST',headers:{'Content-Type':file.type,'X-Workbench-Token':token},body:file});const value=await result.json();if(!result.ok)throw Error(value.error);w.symbol=value.symbol;changed();renderWords();}catch(err){toast(err.message);}};
  if($('#clear-symbol'))$('#clear-symbol').onclick=()=>{w.symbol='';changed();renderWords();};
  $('#add-sense').onclick=()=>{const p=d.parts.find(p=>!p.archived);if(!p){toast('先在词性管理中添加一种词性。');return;}w.senses.push({id:uid('s'),text:'新词义',posId:p.id,notes:'',archived:false,engineMeaning:''});changed();renderWords();};
  $$('#meanings [data-sense]').forEach(container=>container.oninput=ev=>{if(!ev.target.name)return;const s=w.senses.find(s=>s.id===container.dataset.sense);s[ev.target.name]=ev.target.value;changed();});
  $$('[data-delete-sense]').forEach(b=>b.onclick=()=>removeItem('sense',b.dataset.deleteSense,'移除这个词义'));
  $$('[data-restore-sense]').forEach(b=>b.onclick=()=>{w.senses.find(s=>s.id===b.dataset.restoreSense).archived=false;changed();renderWords();});
  $('#manage-parts').onclick=()=>{sub='parts';selection='';renderWords();};bindFields('#word-notes',w);bindFields('#word-code',w);attachRequest('word',w.id,'#word-detail .detail-head');
}
function renderParts(){
  const parts=d.parts.filter(p=>!p.archived);if(!parts.some(p=>p.id===selection))selection=parts[0]?.id||'';
  $('#word-content').innerHTML=`<div class="pagebar"><div><h2>词性由你定义</h2><p>词性归属在每个词义上设置。语法中的词性积木会匹配该类别的所有有效词义。</p></div><button id="add-part" class="primary">＋ 添加词性</button></div><div class="split"><div class="list">${parts.map(p=>`<button class="grammar-card ${selection===p.id?'active':''}" data-part="${e(p.id)}"><b>${e(p.name)}</b><span class="note">${affected(d,'part',p.id).senses} 个词义 · ${affected(d,'part',p.id).grammars.length} 条语法引用</span></button>`).join('')}${d.parts.filter(p=>p.archived).map(p=>`<p class="note">已移除：${e(p.name)} <button class="tiny" data-restore-part="${e(p.id)}">恢复</button></p>`).join('')}</div><div id="part-detail"></div></div>`;
  $('#add-part').onclick=()=>{const p={id:uid('p'),name:'新词性',notes:'',archived:false};d.parts.push(p);selection=p.id;changed();renderWords();};
  $$('[data-part]').forEach(b=>b.onclick=()=>{selection=b.dataset.part;renderParts();});$$('[data-restore-part]').forEach(b=>b.onclick=()=>{d.parts.find(p=>p.id===b.dataset.restorePart).archived=false;changed();renderParts();});
  const p=d.parts.find(p=>p.id===selection);if(!p)return;
  $('#part-detail').innerHTML=`<article class="panel"><div class="detail-head"><h2>${e(p.name)}</h2><button class="tiny danger" id="remove-part">移除词性</button></div><div class="fields" id="part-fields">${field('词性名称','name',p.name,'input')}${field('这个词性接受什么样的词义','notes',p.notes,'long')}</div><div class="section"><h3>使用这个词性的词义</h3><div class="inline-ref">${[...senseIndex(d,true).values()].filter(s=>s.posId===p.id&&!s.archived).map(s=>`<span class="pill">${sym(s.symbol,'mini')} ${e(s.text)}</span>`).join('')||'<p class="note">尚无词义。</p>'}</div></div></article>`;
  attachRequest('part',p.id,'#part-detail .detail-head');bindFields('#part-fields',p);$('#remove-part').onclick=()=>removeItem('part',p.id,'移除这个词性');
}
function renderSync(){const diff=syncChanges(d);$('#word-content').innerHTML=`<div class="pagebar"><div><h2>供下一次 SO 更新使用</h2><p>这里比较设计与首次导入基线。不会自动更新游戏或把引擎内容覆盖回词库。</p></div><button id="refresh-source">读取最新 SO 事实</button></div><div class="panel"><p class="note">当前事实快照：${snapshot.words.length} 词，${snapshot.rules.length} 条登记句子。设计结构与运行时数据分别保存。</p>${diff.map(x=>`<div class="history-entry"><b>${e(x.code||'新词')}</b> ${badge('draft',x.kind)}<p>${e(x.path||'没有源 SO')}</p></div>`).join('')||'<p class="empty">词库与导入基线一致。</p>'}<p class="note spacer">语法和句子也有自己的编号，开发任务可直接引用。已完成一次引擎同步后，需要任务核验再更新对应基线；本页不自动认定已同步。</p></div>`;$('#refresh-source').onclick=async()=>{if(dirty)return toast('请先保存当前设计。');try{snapshot=(await post('/api/source',{revision})).snapshot;renderSync();toast('已更新引擎事实快照，设计词库未被覆盖。');}catch(err){toast(err.message);}};}

function slotLabel(s){return s.kind==='pos'?(d.parts.find(p=>p.id===s.ref)?.name||'已移除词性'):(senseIndex(d,true).get(s.ref)?.text||'已移除词义');}
function renderGrammar(){
  const active=d.grammars.filter(g=>!g.archived);if(!active.some(g=>g.id===selection))selection=active[0]?.id||'';
  $('#workspace').innerHTML=`<div class="pagebar"><div><h2>用词性与指定词义拼出结构</h2><p>定义一次共同逻辑，再查看该语法展开的所有句子。</p></div><button id="add-grammar" class="primary">＋ 添加语法</button></div><div class="split"><div><div class="list scroll">${active.map(g=>`<button class="grammar-card ${selection===g.id?'active':''}" data-grammar="${e(g.id)}"><span class="id">${displayRef(g.id)}</span><small>${g.enabled?allRows().filter(r=>r.active&&r.grammarIds.includes(g.id)).length+' 句':'未启用'}</small><b>${e(g.title)}</b><div class="note">${g.slots.map(s=>e(slotLabel(s))).join(' · ')}</div></button>`).join('')||'<p class="empty">添加一条语法开始。</p>'}</div>${d.grammars.filter(g=>g.archived).map(g=>`<p class="note">${g.id} ${e(g.title)} <button class="tiny" data-restore-grammar="${g.id}">恢复</button></p>`).join('')}</div><div id="grammar-detail"></div></div>`;
  $$('[data-grammar]').forEach(b=>b.onclick=()=>{navigate(()=>{selection=b.dataset.grammar;grammarPage='definition';grammarSentence='';});});
  $$('[data-restore-grammar]').forEach(b=>b.onclick=()=>{d.grammars.find(g=>g.id===b.dataset.restoreGrammar).archived=false;changed();render();});
  $('#add-grammar').onclick=()=>{const p=d.parts.find(p=>!p.archived);if(!p)return toast('请先创建词性。');const g={id:uid('G'),title:'新语法',slots:[{id:uid('slot'),kind:'pos',ref:p.id}],logic:'',lifecycle:'',notes:'',source:'',status:'draft',enabled:true,archived:false,constraints:[],exceptions:[]};d.grammars.push(g);selection=g.id;grammarPage='definition';changed();render();};
  const g=d.grammars.find(g=>g.id===selection);if(!g)return;
  $('#grammar-detail').innerHTML=`<article class="panel"><div class="detail-head"><div><span class="id">${displayRef(g.id)}</span><h2>${e(g.title)}</h2></div><button id="remove-grammar" class="tiny danger">移除语法</button></div><div class="subnav"><button data-gpage="definition" class="${grammarPage==='definition'?'active':''}">结构与逻辑</button><button data-gpage="sentences" class="${grammarPage==='sentences'?'active':''}">展开句子 <span class="count">${allRows().filter(r=>r.active&&r.grammarIds.includes(g.id)).length}</span></button></div><div id="grammar-content"></div></article>`;
  $('#remove-grammar').onclick=()=>removeItem('grammar',g.id,'移除这个语法');
  $$('[data-gpage]').forEach(b=>b.onclick=()=>{navigate(()=>{grammarPage=b.dataset.gpage;grammarSentence='';});});
  if(!grammarSentence)attachRequest('grammar',g.id,'#grammar-detail .detail-head');
  if(grammarPage==='sentences'&&grammarSentence){
    $('#grammar-content').innerHTML='<button class="text-link" id="back-grammar-list">← 返回 '+e(g.title)+'的句子列表</button><div id="sentence-detail" class="spacer"></div>';
    $('#back-grammar-list').onclick=()=>{navigate(()=>{grammarSentence='';});window.scrollTo(0,grammarListScroll);};renderSentenceDetail();return;
  }
  if(grammarPage==='sentences'){
    const expandedRows=allRows().filter(r=>r.active&&r.grammarIds.includes(g.id));
    $('#grammar-content').innerHTML=`${dirty?'<div class="warning">这里显示上次保存后的结果。保存并更新后，新结构会重新展开；既有编号与笔记保留。</div>':''}<div class="section-head"><p class="note">点击句子编号，查看继承逻辑并填写例外。${expandedRows.length>60?` 当前显示前 60 条，共 ${expandedRows.length} 条；在所有可能性中查看查看全部。`:``}</p><button class="tiny" id="open-grammar-sentences">在所有可能性中查看</button></div><div class="list">${expandedRows.slice(0,60).map(sentenceCard).join('')||'<p class="empty">尚无匹配句子，请检查结构并保存。</p>'}</div>`;
    $('#open-grammar-sentences').onclick=()=>{navigate(()=>{filterGrammar=g.id;filterState='active';page='sentences';selection='';grammarSentence='';search='';offset=0;});};wireSentenceButtons();return;
  }
  renderGrammarDefinition(g);
}
function renderGrammarDefinition(g){
  const ix=senseIndex(d),parts=d.parts.filter(p=>!p.archived);
  $('#grammar-content').innerHTML=`<div class="grid2" id="grammar-basics">${field('语法名称','title',g.title,'input')}<label class="check-label"><input type="checkbox" name="designPending" ${g.designPending?'checked':''}>待设计（给自己的提醒）</label><label class="check-label"><input type="checkbox" name="enabled" ${g.enabled?'checked':''}>启用并展开此语法</label></div><div class="builder"><div class="section-head"><h3>句式结构</h3><small>拖拽排序 · × 移除槽位</small></div><div class="slots" id="slots">${g.slots.map((s,n)=>`<div class="slot ${s.kind==='sense'?'fixed':''}" draggable="true" data-slot="${e(s.id)}" data-index="${n}"><span class="slot-num">${n+1}</span>${s.kind==='sense'?sym(ix.get(s.ref)?.symbol,'mini'):''}<div><strong>${e(slotLabel(s))}</strong><small>${s.kind==='pos'?'任意此词性':'指定这个词义'}</small></div><button data-slot-left="${n}" aria-label="槽位 ${n+1} 左移">‹</button><button data-slot-right="${n}" aria-label="槽位 ${n+1} 右移">›</button><button data-slot-remove="${e(s.id)}" aria-label="移除槽位 ${n+1}">×</button></div>`).join('')}<div class="drop-end" id="drop-end">拖到这里添加</div></div><div class="palette-title"><button data-palette="pos" class="${palette==='pos'?'active':''}">词性</button><button data-palette="sense" class="${palette==='sense'?'active':''}">指定词义</button><span class="note">点选或拖入结构</span></div><div class="palette">${palette==='pos'?parts.map(p=>`<button draggable="true" data-pick-kind="pos" data-pick-ref="${e(p.id)}">${e(p.name)}</button>`).join(''):[...ix.values()].map(s=>`<button draggable="true" data-pick-kind="sense" data-pick-ref="${e(s.id)}">${sym(s.symbol,'mini')} ${e(s.text)}</button>`).join('')}</div></div><div class="fields" id="grammar-logic"><p class="note">在这里自由描述这条语法的规则、适用条件和具体表现。展开的句子会沿用这份说明，单句特例可在句子里补充。</p>${field('规则说明','logic',g.logic,'long')}${field('拆句、条件解除之后','lifecycle',g.lifecycle)}${field('备注','notes',g.notes)}<details><summary>来源记录</summary>${field('依据','source',g.source,'input')}<p class="note">旧分类：${e(STATES[g.status]||g.status)}，不代表开发或验收进度。</p></details></div><details class="section"><summary>共同条件说明（可选）</summary><p class="note">只在条件影响多个句子时填写。用文字描述对象和情况即可；单句的特殊效果请在展开句子里写。</p><button id="add-exception" class="tiny">＋ 添加条件说明</button>${g.exceptions.map((x,n)=>`<div class="exception" data-exception="${n}"><div class="section-head"><b>${e(x.title)}</b><button data-remove-exception="${n}" class="tiny">移除说明</button></div>${field('名称','title',x.title,'input')}${x.slotId&&x.senseId?`<p class="note">保留的适用范围：句式中的“${e(slotLabel(g.slots.find(s=>s.id===x.slotId)||{}))}”取“${e(ix.get(x.senseId)?.text||'已移除词义')}”时。</p>`:''}${field('什么情况下适用','condition',x.condition)}${field('具体行为（有替代时写明替代哪一部分）','effect',x.effect)}</div>`).join('')}</details>${g.constraints.length?`<details class="section"><summary>此前保存的组合条件</summary><p class="note">这些旧条件仍参与展开。新增条件可直接写在备注中，交给开发事项处理。</p>${g.constraints.map(c=>`<p>“${e(slotLabel(g.slots.find(s=>s.id===c.left)||{}))}”与“${e(slotLabel(g.slots.find(s=>s.id===c.right)||{}))}”${c.kind==='differentWord'?'不能来自同一个词':'不能是同一个词义'}。</p>`).join('')}</details>`:''}`;
  bindFields('#grammar-basics',g);bindFields('#grammar-logic',g);
  $$('[data-palette]').forEach(b=>b.onclick=()=>{palette=b.dataset.palette;renderGrammarDefinition(g);});
  const insert=(kind,ref,index=g.slots.length)=>{if(g.slots.length>=8)return toast('最多 8 个槽位；请拆分语法。');g.slots.splice(index,0,{id:uid('slot'),kind,ref});changed();renderGrammarDefinition(g);};
  $$('[data-pick-kind]').forEach(b=>{b.onclick=()=>insert(b.dataset.pickKind,b.dataset.pickRef);b.ondragstart=ev=>ev.dataTransfer.setData('text/plain',JSON.stringify({kind:b.dataset.pickKind,ref:b.dataset.pickRef}));});
  $$('#slots [data-slot]').forEach(el=>el.ondragstart=ev=>{ev.dataTransfer.setData('text/plain',JSON.stringify({slot:el.dataset.slot}));ev.stopPropagation();});
  const drop=(ev,index)=>{ev.preventDefault();try{const data=JSON.parse(ev.dataTransfer.getData('text/plain'));if(data.slot){const from=g.slots.findIndex(s=>s.id===data.slot);if(from<0)return;const [s]=g.slots.splice(from,1);g.slots.splice(from<index?index-1:index,0,s);changed();renderGrammarDefinition(g);}else if(['pos','sense'].includes(data.kind)&&(data.kind==='pos'?parts.some(p=>p.id===data.ref):ix.has(data.ref)))insert(data.kind,data.ref,index);}catch{toast('请从当前编辑器拖入词性或词义。');}};
  $$('#slots [data-index]').forEach(el=>{el.ondragover=ev=>{ev.preventDefault();el.classList.add('dragover');};el.ondragleave=()=>el.classList.remove('dragover');el.ondrop=ev=>drop(ev,Number(el.dataset.index));});
  $('#drop-end').ondragover=ev=>ev.preventDefault();$('#drop-end').ondrop=ev=>drop(ev,g.slots.length);
  $$('[data-slot-remove]').forEach(b=>b.onclick=()=>{const id=b.dataset.slotRemove;g.slots=g.slots.filter(s=>s.id!==id);g.constraints=g.constraints.filter(c=>c.left!==id&&c.right!==id);for(const x of g.exceptions)if(x.slotId===id){x.slotId='';x.senseId='';x.condition='【原限定位置已移除，请复核】'+x.condition;}changed();renderGrammarDefinition(g);});
  for(const [key,step] of [['slotLeft',-1],['slotRight',1]])$$('[data-'+key.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())+']').forEach(b=>b.onclick=()=>{const i=Number(b.dataset[key]),j=i+step;if(j<0||j>=g.slots.length)return;[g.slots[i],g.slots[j]]=[g.slots[j],g.slots[i]];changed();renderGrammarDefinition(g);});
  $('#add-exception').onclick=()=>{g.exceptions.push({id:uid('exception'),title:'条件说明',mode:'supplement',condition:'',effect:'',slotId:'',senseId:''});changed();renderGrammarDefinition(g);};
  $$('[data-exception]').forEach(el=>el.oninput=ev=>{if(ev.target.name){g.exceptions[Number(el.dataset.exception)][ev.target.name]=ev.target.value;changed();}});
  $$('[data-remove-exception]').forEach(b=>b.onclick=()=>{g.exceptions.splice(Number(b.dataset.removeException),1);changed();renderGrammarDefinition(g);});
}

function sentenceCard(r){return `<button class="sentence-row ${selection===r.id?'active':''}" data-sentence="${r.id}"><span class="rowmeta"><span class="id">${r.id}</span>${!r.active?badge('retired','已退出范围'):badge(recordState(d,r)==='stale'?'stale':'inherited',recordState(d,r)==='stale'?'设计需复核':MODES[r.note.mode])}</span><span class="line">${r.tokens.map(t=>sym(t.symbol,'mini')).join('')}</span><span class="interpretation">${e(sentenceTitle(r))}</span></button>`;}
function openSentence(id){navigate(()=>{if(page==='grammar'){if(!grammarSentence)grammarListScroll=window.scrollY;grammarSentence=id;grammarPage='sentences';}else{page='sentences';selection=id;search=id;filterGrammar='';filterState='all';offset=0;}});}
function wireSentenceButtons(){$$('[data-sentence]').forEach(b=>b.onclick=()=>openSentence(b.dataset.sentence));}
function renderSentences(){
  $('#workspace').innerHTML=`<div class="pagebar"><div><h2>用编号讨论每一个明确句义</h2><p>相同词义序列共用编号。匹配多条语法时并列显示；重新计算与排序不改号。</p></div><span class="count">${allRows().filter(r=>r.active).length} 当前 · ${allRows().filter(r=>!r.active).length} 历史</span></div>${dirty?'<div class="warning">当前有未保存修改。这里保留上次保存的展开结果；点击“保存并更新”应用结构变化。</div>':''}<div class="filters"><input id="sentence-search" aria-label="搜索句子" placeholder="输入编号 S-0042、词义或笔记内容…" value="${e(search)}"><select id="grammar-filter" aria-label="语法筛选">${option('','全部语法',filterGrammar)}${d.grammars.map(g=>option(g.id,g.id+' '+g.title,filterGrammar)).join('')}</select><select id="state-filter" aria-label="句子状态">${[['active','当前组合'],['all','全部含历史'],['retired','已退出范围'],['stale','需复核'],['overlap','语法重叠'],['annotated','有具体标注']].map(([k,v])=>option(k,v,filterState)).join('')}</select></div><div class="split"><div><p class="note" id="result-count"></p><div class="list" id="sentence-list"></div><div class="pager" id="pager"></div></div><div id="sentence-detail"></div></div>`;
  $('#sentence-search').oninput=ev=>{search=ev.target.value;offset=0;renderSentenceList();};$('#grammar-filter').onchange=ev=>{filterGrammar=ev.target.value;offset=0;renderSentenceList();};$('#state-filter').onchange=ev=>{filterState=ev.target.value;offset=0;renderSentenceList();};renderSentenceList();
}
function renderSentenceList(){
  const filtered=allRows().filter(r=>(!search||[r.id,sentenceTitle(r),r.note.effect,r.note.notes].join(' ').toLowerCase().includes(search.toLowerCase()))&&(!filterGrammar||r.grammarIds.includes(filterGrammar))&&(filterState==='all'||filterState==='active'&&r.active||filterState==='retired'&&!r.active||filterState==='stale'&&recordState(d,r)==='stale'||filterState==='overlap'&&r.grammarIds.length>1||filterState==='annotated'&&(r.note.mode!=='inherit'||r.note.notes||r.note.effect)));
  if(offset>=filtered.length)offset=0;const visible=filtered.slice(offset,offset+PAGE_SIZE);if(!filtered.some(r=>r.id===selection))selection=visible[0]?.id||'';
  $('#result-count').textContent=`${filtered.length} 条结果 · 每页 ${PAGE_SIZE} 条`;
  $('#sentence-list').innerHTML=visible.map(sentenceCard).join('')||'<p class="empty">没有匹配的句子。</p>';
  $('#pager').innerHTML=`<button id="previous-page" ${offset===0?'disabled':''}>上一页</button><span>${filtered.length?Math.floor(offset/PAGE_SIZE)+1:0} / ${Math.ceil(filtered.length/PAGE_SIZE)}</span><button id="next-page" ${offset+PAGE_SIZE>=filtered.length?'disabled':''}>下一页</button>`;
  $('#previous-page').onclick=()=>{offset-=PAGE_SIZE;selection='';renderSentenceList();};$('#next-page').onclick=()=>{offset+=PAGE_SIZE;selection='';renderSentenceList();};
  $$('#sentence-list [data-sentence]').forEach(b=>b.onclick=()=>{navigate(()=>{selection=b.dataset.sentence;});});renderSentenceDetail();
}
function renderSentenceDetail(){
  const r=allRows().find(r=>r.id===(grammarSentence||selection));if(!r){$('#sentence-detail').innerHTML='';return;}
  const gs=d.grammars.filter(g=>r.grammarIds.includes(g.id)),related=d.relations.filter(c=>!c.archived&&c.sentenceIds.includes(r.id));
  $('#sentence-detail').innerHTML=`<article class="panel"><div class="detail-head"><div><span class="id">${r.id}</span><h2>${e(sentenceTitle(r))}</h2></div><button class="tiny" id="copy-reference">复制编号</button></div><div class="sentence-hero">${r.tokens.map(t=>`<div class="sentence-token">${sym(t.symbol)}<small>${e(t.text)}</small></div>`).join('')}</div>${!r.active?'<div class="warning">这个句义已不在当前展开范围。编号与原标注永久保留；相同词义序列重新出现时继续使用此编号。</div>':''}${recordState(d,r)==='stale'?'<div class="warning">词义、语法或关联记录已变化。原笔记保留，请重新检查；可以在历史中查看之前版本。</div>':''}${r.grammarIds.length>1?'<div class="warning">匹配多条语法。请检查默认行为是否一致，工具不会静默选取其中一条。</div>':''}<h3>沿用的语法规则说明</h3>${gs.map(g=>`<div class="inherited"><div class="section-head"><span><span class="id">${displayRef(g.id)}</span> ${e(g.title)}</span><button class="tiny" data-open-grammar="${g.id}">编辑语法</button></div><p>${e(g.logic||'尚未填写规则说明。')}</p>${g.lifecycle?`<details><summary>拆句与生命周期</summary><p>${e(g.lifecycle)}</p></details>`:''}${eligibleExceptions(g,r).map(x=>`<details><summary>例外：${e(x.title)} · ${e(MODES[x.mode])}</summary><p>条件：${e(x.condition||'未填写')}</p><p>${e(x.effect)}</p></details>`).join('')}</div>`).join('')||'<p class="note">当前没有有效匹配语法。</p>'}<section class="section"><div class="section-head"><h3>这个句子的特殊说明</h3>${badge(recordState(d,r)==='stale'?'stale':'inherited',recordState(d,r)==='stale'?'设计需复核':MODES[r.note.mode])}</div><p class="note">沿用语法：无需另写效果。补充细节：增加注意事项。采用特殊行为：写明改用什么行为、替代哪一部分；未替代的规则仍适用。没想好时选“待设计”。</p><div class="fields" id="sentence-fields"><div class="grid2"><label>如何处理默认行为<select name="mode">${Object.entries(MODES).map(([k,v])=>option(k,v,r.note.mode)).join('')}</select></label></div>${field('具体效果、操作与表现','effect',r.note.effect,'long')}${field('适用实体与世界条件','condition',r.note.condition)}${field('拆句或条件解除之后','lifecycle',r.note.lifecycle)}${field('备注','notes',r.note.notes,'long')}<details><summary>来源与旧标注</summary>${field('依据','evidence',r.note.evidence)}<p class="note">旧分类：${e(STATES[r.note.status]||r.note.status)}，不代表开发或验收进度。</p></details></div><div class="actions spacer"><button id="acknowledge">本次已复核这些依据</button><button id="sentence-history">查看修改历史</button></div></section><section class="section"><div class="section-head"><h3>句子之间的关系</h3><button id="add-relation" class="tiny">＋ 关联其他编号</button></div>${related.map(c=>`<div class="relation"><div class="section-head"><b>${e(c.title)}</b><button data-edit-relation="${e(c.id)}" class="tiny">编辑</button></div><div class="inline-ref">${c.sentenceIds.map(id=>`<button class="tiny" data-related-id="${id}">${id}</button>`).join('')}</div><p>${e(c.result||'结果待设计')}</p><small>${e(c.condition)}</small></div>`).join('')||'<p class="note">还没有关联。冲突、共存或特殊联动只写一份，在所有相关句子下显示。</p>'}</section></article>`;
  attachRequest('sentence',r.id,'#sentence-detail .detail-head');
  $('#copy-reference').onclick=async()=>{try{await navigator.clipboard.writeText(r.id);toast('已复制 '+r.id);}catch{toast('句子编号：'+r.id);}};
  $$('[data-open-grammar]').forEach(b=>b.onclick=()=>{navigate(()=>{grammarPage='definition';grammarSentence='';page='grammar';selection=b.dataset.openGrammar;});});
  bindFields('#sentence-fields',r.note,()=>{delete r.note.acknowledge;});
  $('#acknowledge').onclick=()=>{r.note.acknowledge=true;changed();toast('已标记本次复核，保存后记录对应的依据版本。');};
  $('#sentence-history').onclick=()=>showHistory(r.id);
  $('#add-relation').onclick=()=>{const c={id:uid('R'),title:'新关联',kind:'conflict',status:'draft',sentenceIds:[r.id],condition:'',order:'',result:'',notes:'',archived:false};d.relations.push(c);changed();editRelation(c);};
  $$('[data-edit-relation]').forEach(b=>b.onclick=()=>editRelation(d.relations.find(c=>c.id===b.dataset.editRelation)));$$('[data-related-id]').forEach(b=>b.onclick=()=>openSentence(b.dataset.relatedId));
}
function editRelation(c){
  const kinds={conflict:'冲突',coexist:'共存',effect:'特殊联动',capacity:'容量／占位',sequence:'顺序影响'};
  modal(`<h2>关联句子 · ${e(displayRef(c.id))}</h2><p class="note">一次编辑，同时显示在所有关联编号下。</p><div class="fields" id="relation-fields">${field('关系名称','title',c.title,'input')}<div class="grid2"><label>关系类型<select name="kind">${Object.entries(kinds).map(([k,v])=>option(k,v,c.kind)).join('')}</select></label></div>${field('条件','condition',c.condition)}${field('成立或操作顺序','order',c.order)}${field('预期结果或冲突裁决','result',c.result,'long')}${field('备注与依据','notes',c.notes)}</div><div class="section"><h3>关联编号</h3>${c.sentenceIds.map(id=>`<span class="pill">${id}<button data-unlink="${id}" aria-label="移除关联 ${id}">×</button></span>`).join('')}<div class="actions spacer"><input id="link-id" aria-label="关联句子编号" placeholder="输入 S-0042" list="sentence-ids"><datalist id="sentence-ids">${allRows().map(r=>`<option value="${r.id}">${e(sentenceTitle(r))}</option>`).join('')}</datalist><button id="link-add">加入编号</button></div></div><div class="actions spacer"><button id="relation-done" class="primary">完成编辑</button><button id="relation-archive" class="danger">移除这条关联</button></div>`);
  bindFields('#relation-fields',c);$('#link-add').onclick=()=>{const id=$('#link-id').value.trim().toUpperCase();if(!allRows().some(r=>r.id===id))return toast('没有这个编号，请先保存词库或语法以生成新句子。');if(!c.sentenceIds.includes(id)){c.sentenceIds.push(id);changed();editRelation(c);}};
  $$('[data-unlink]').forEach(b=>b.onclick=()=>{c.sentenceIds=c.sentenceIds.filter(id=>id!==b.dataset.unlink);changed();editRelation(c);});
  $('#relation-done').onclick=()=>{$('#modal').close();renderSentenceDetail();};$('#relation-archive').onclick=()=>{removeItem('relation',c.id,'移除这条关联');};
}

async function post(url,data){const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-Workbench-Token':token},body:JSON.stringify(data)});const value=await res.json();if(!res.ok)throw Error(value.error||'请求失败');return value;}
function acceptSaved(result){selection=result.idMap?.[selection]||selection;filterGrammar=result.idMap?.[filterGrammar]||filterGrammar;d=result.design;savedDesign=structuredClone(d);revision=result.revision;issues=result.issues;stats=result.stats;dirty=false;clearTimeout(draftTimer);localStorage.removeItem(DRAFT);$('#banner').innerHTML='';$('#save-state').textContent='已保存到项目';$('#save-state').classList.remove('dirty');render();}
function setBusy(value){busy=value;$('#workspace').inert=value;$('#modal-body').inert=value;for(const id of ['save','history','export'])$('#'+id).disabled=value;}
async function save(){const errors=validate(d,{allowDrafts:true});if(errors.length){toast(errors.join('；'));return false;}persistDraft();setBusy(true);try{const result=await post('/api/save',{design:d,revision});acceptSaved(result);toast(`已保存 · ${stats.active} 条当前句子 · 更新 ${stats.recomputed} 条语法，复用 ${stats.reused} 条语法的展开结果。`);return true;}catch(err){toast(err.message);return false;}finally{setBusy(false);}}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function report(){const lines=['# V3 语言设计','','这是独立设计文档，不会自动修改游戏。新增结构在保存后分配稳定句子编号。','','## 词性',''];for(const p of d.parts)lines.push(`- ${p.name}${p.archived?'（已移除）':''}：${p.notes}`);lines.push('','## 词库','');for(const w of d.words){lines.push(`### 词条 ${w.code||w.id}${w.archived?'（已移除）':''}`,`符号：${w.symbol||'空白'}`,`SO：${w.source?.path||'待建立映射'}`,w.notes);for(const s of w.senses)lines.push(`- ${s.text}；词性：${d.parts.find(p=>p.id===s.posId)?.name}；${s.archived?'已移除':'有效'}。${s.notes}`);lines.push('');}lines.push('## 语法','');for(const g of d.grammars){lines.push(`### ${g.id} ${g.title}`,`状态：${STATES[g.status]}；${g.archived?'已移除':g.enabled?'启用':'停用'}`,`结构：${g.slots.map(s=>(s.kind==='pos'?'任意词性：':'指定词义：')+slotLabel(s)).join(' → ')}`,`限制：${g.constraints.map(c=>JSON.stringify(c)).join('；')||'无'}`,`规则说明：${g.logic}`,`拆句：${g.lifecycle}`,`备注：${g.notes}`,`依据：${g.source}`);for(const x of g.exceptions)lines.push(`例外 ${x.title}：${MODES[x.mode]}；条件 ${x.condition}；行为 ${x.effect}；限定位置 ${x.slotId||'不限'}，词义 ${senseIndex(d,true).get(x.senseId)?.text||'不限'}`);lines.push('');}lines.push('## 已编号句子','');for(const r of allRows())lines.push(`### ${r.id} ${sentenceTitle(r)}`,`${r.active?'当前':'已退出范围'}；${r.grammarIds.join('、')}；${STATE_LABEL[recordState(d,r)]}`,`处理方式：${MODES[r.note.mode]}`,`效果：${r.note.effect||'沿用相关语法（需满足条件）'}`,`条件：${r.note.condition}`,`拆句：${r.note.lifecycle}`,`笔记：${r.note.notes}`,`依据：${r.note.evidence}`,'');lines.push('## 句子关联','');for(const c of d.relations)lines.push(`### ${c.id} ${c.title}${c.archived?'（已移除）':''}`,`${STATES[c.status]}；${c.sentenceIds.join('、')}`,`条件：${c.condition}`,`顺序：${c.order}`,`结果：${c.result}`,`备注：${c.notes}`,'');for(const t of d.tasks||[])lines.push(`### ${t.id} ${t.title}`,`版本：${t.version}；进度：${TASK_STATES[t.status]}；来源：${t.sourceKind} ${t.sourceId}`,t.request,`设计已变化：${taskOutdated(d,t)?'是':'否'}`, ...t.events.map(ev=>`${ev.at} ${TASK_STATES[ev.status]}：${ev.note}`),'');return lines.join('\n');}
async function showHistory(ref=''){
  try{
    const response=await fetch('/api/history');if(!response.ok)throw Error('历史读取失败');const list=await response.json(),cache=new Map();
    async function getVersion(rev){if(!rev)return null;if(!cache.has(rev)){const response=await fetch('/api/history/'+rev);if(!response.ok)throw Error('历史快照不可用：'+rev.slice(0,8));cache.set(rev,await response.json());}return cache.get(rev);}
    const pairs=await Promise.all(list.map(async h=>{const after=await getVersion(h.revision),before=await getVersion(h.parentRevision);return {h,after,before,diff:documentDiff(before?.design,after.design,ref)};}));
    const currentEvent=list.find(h=>h.revision===revision)?.eventId;
    const drawList=()=>{
      const visible=pairs.filter(p=>!ref||p.diff.length);
      modal(`<h2>${ref?e(ref)+' 的修改历史':'历史与版本'}</h2><div class="subnav"><button class="active">保存历史</button><button id="open-releases">命名版本</button></div><p class="note">记录成功保存后的完整设计，未保存的输入属于浏览器草稿。默认查看每次保存前后的变化。${ref?'包含本句标注及相关词义、语法和句间关系的变化。':''}${dirty?'当前还有未保存内容，可单独与历史比较。':''}</p><div class="history-list">${visible.map(({h,diff,before})=>`<div class="history-entry"><b>${e(h.label)}</b>${h.eventId===currentEvent?' '+badge('confirmed','当前保存版本'):''}<small>${e(new Date(h.at).toLocaleString())} · ${h.revision.slice(0,8)}</small><p>${e(!before?'初始快照；没有更早版本。':diff.length?diff.map(x=>x.id+' '+x.title+(x.related?'（关联设计）':'')+'：'+x.fields.map(f=>f.field||'整条记录').join('、')).join('\n'):'没有设计内容差异。')}</p><div class="actions"><button data-view-history="${h.eventId}" class="tiny">${before?'查看本次修改':'查看初始内容'}</button><button data-current-history="${h.eventId}" class="tiny">与当前编辑比较</button><button data-restore-history="${h.eventId}" class="tiny" ${dirty||h.revision===revision?'disabled':''}>恢复此版本</button></div></div>`).join('')||'<p class="empty">暂无相关历史。</p>'}</div>`);
      $('#open-releases').onclick=showReleases;
      $('[data-view-history]').forEach(b=>b.onclick=()=>drawDiff(pairs.find(p=>p.h.eventId===b.dataset.viewHistory),false));
      $$('[data-current-history]').forEach(b=>b.onclick=()=>drawDiff(pairs.find(p=>p.h.eventId===b.dataset.currentHistory),true));
      $$('[data-restore-history]').forEach(b=>b.onclick=async()=>{if(dirty)return toast('请先保存当前修改。');try{setBusy(true);acceptSaved(await post('/api/restore',{revision,target:pairs.find(p=>p.h.eventId===b.dataset.restoreHistory).h.revision}));$('#modal').close();toast('设计已恢复；编号和开发进度保留。');}catch(err){toast(err.message);}finally{setBusy(false);}});
    };
    const drawDiff=(pair,withCurrent)=>{
      const left=withCurrent?pair.after.design:pair.before?.design,right=withCurrent?d:pair.after.design,diff=documentDiff(left,right,ref);
      const leftTitle=withCurrent?'所选历史版本':pair.before?'保存前':'尚无记录',rightTitle=withCurrent?'当前编辑内容'+(dirty?'（含未保存修改）':''):'保存后';
      const value=(v,f,kind)=>{const text=historyValue(v,f.path,kind);return f.path.at(-1)==='symbol'&&typeof v==='string'&&v.startsWith('/symbols/')?sym(v,'big')+'<p>'+e(text)+'</p>':'<pre>'+e(text)+'</pre>';};
      modal(`<h2>${withCurrent?'与当前编辑比较':'本次保存的修改'}</h2><p class="note">${e(new Date(pair.h.at).toLocaleString())} · ${e(pair.h.label)}。左侧：${leftTitle}；右侧：${rightTitle}。${!withCurrent&&pair.h.inferredParent?'旧记录按保存时间衔接前一版本。':''}</p>${diff.length?diff.map(row=>`<section class="history-change"><h3>${e(row.id)} · ${e(row.title)}${row.related?' <small>关联设计变化</small>':''}</h3>${row.fields.map(f=>`<div class="change-field"><h4>${e(f.field||'整条记录')}${f.path.at(-1)==='status'&&row.kind!=='tasks'?'（历史分类，不代表开发进度）':''}</h4><div class="diff"><div><small>${leftTitle}</small>${value(f.before,f,row.kind)}</div><div><small>${rightTitle}</small>${value(f.after,f,row.kind)}</div></div></div>`).join('')}</section>`).join(''):'<p class="empty">两份内容一致，没有差异。要看那次保存改了什么，请返回历史选择“查看本次修改”。</p>'}<details class="technical"><summary>原始数据（完整快照）</summary><div class="diff"><pre>${e(JSON.stringify(left,null,2)||'没有更早版本')}</pre><pre>${e(JSON.stringify(right,null,2))}</pre></div></details><div class="actions spacer"><button id="download-version">导出该版本完整 JSON</button><button id="back-history">返回历史</button></div>`);
      $('#download-version').onclick=()=>download('V3-history-'+pair.h.revision.slice(0,8)+'.json',JSON.stringify(pair.after.design,null,2));$('#back-history').onclick=drawList;
    };
    drawList();
  }catch(err){toast(err.message);}
}
$('#save').onclick=save;$('#history').onclick=()=>showHistory();$('#modal-close').onclick=()=>{$('#modal').close();if(page==='sentences'||grammarSentence)renderSentenceDetail();};
$('#export').onclick=()=>{modal('<h2>导出当前设计</h2><p class="note">包含尚未保存的编辑。稳定编号以已保存结果为准。</p><div class="actions"><button id="export-json">完整 JSON</button><button id="export-markdown">可读 Markdown</button></div>');$('#export-json').onclick=()=>download('V3-language-design.json',JSON.stringify(d,null,2));$('#export-markdown').onclick=()=>download('V3-language-design.md',report(),'text/markdown;charset=utf-8');};
window.addEventListener('beforeunload',ev=>{if(dirty){persistDraft();ev.preventDefault();ev.returnValue='';}});
window.addEventListener('pagehide',persistDraft);window.addEventListener('unhandledrejection',ev=>toast(ev.reason?.message||'操作失败'));window.addEventListener('error',ev=>toast(ev.message));
try{
  const res=await fetch('/api/state');if(!res.ok)throw Error('服务尚未准备好');const state=await res.json();d=state.design;savedDesign=structuredClone(d);d.tasks??=[];revision=state.revision;token=state.token;snapshot=state.snapshot;issues=state.issues;stats=state.stats;
  const errors=validate(d);if(errors.length)throw Error(errors.join('；'));$('#save-state').textContent='已从项目载入';if(history.state?.workbench)applyView(history.state.view);render();history.replaceState({workbench:true,depth:history.state?.depth||0,view:viewState()},'');setBusy(false);
  let draft;try{draft=JSON.parse(localStorage.getItem(DRAFT)||'null');}catch{}
  if(draft?.design?.schemaVersion===2&&canonical(draft.design)!==canonical(d)){
    $('#banner').innerHTML=`<div class="banner">发现本浏览器保存的未提交草稿（${e(new Date(draft.at).toLocaleString())}）。${draft.revision!==revision?'它基于旧版设计，恢复后直接保存会被拦截；请先导出，避免覆盖最新内容。':''}<div class="actions"><button id="recover-draft">恢复草稿</button><button id="export-draft">导出草稿</button><button id="discard-draft">使用项目已保存版本</button></div></div>`;
    $('#recover-draft').onclick=()=>{d=draft.design;d.tasks??=[];revision=draft.revision;changed();$('#banner').innerHTML='';render();};$('#export-draft').onclick=()=>download('V3-recovered-draft.json',JSON.stringify(draft.design,null,2));$('#discard-draft').onclick=()=>{localStorage.removeItem(DRAFT);$('#banner').innerHTML='';};
  }
}catch(err){$('#workspace').innerHTML=`<div class="panel"><h2>未能载入设计</h2><p>${e(err.message)}</p><p class="note">请通过“启动工作台.cmd”打开新版服务。</p></div>`;$('#save-state').textContent='载入失败';}


function attachRequest(kind,id,selector){
  const host=$(selector);if(!host)return;const button=document.createElement('button');button.className='tiny';button.textContent='提交开发事项';button.onclick=()=>requestDevelopment(kind,id);host.append(button);
  const t=[...(d.tasks||[])].reverse().find(t=>!t.archived&&t.sourceKind===kind&&t.sourceId===id);if(t){const link=document.createElement('button');link.className='text-link';link.textContent=t.id+' · '+TASK_STATES[t.status]+(taskOutdated(d,t)?' · 设计已变化':'');link.onclick=()=>{taskFilter='all';taskVersion='';go('development',t.id);};host.append(link);}
}
function sourceTitle(kind,id){const r=sourceRecord(d,kind,id);return r?(kind==='word'?wordDescription(r):kind==='sentence'?sentenceTitle(r):r.title||r.name):id;}
function requestDevelopment(kind,id,existing=null){
  const title=existing?.title||sourceTitle(kind,id);
  modal(`<h2>提交开发事项</h2><p class="note">来源：${e(SOURCE_TYPES[kind])} · ${e(sourceTitle(kind,id))}。提交后保存当前设计，并加入开发进度列表；不会自动修改游戏。</p><div class="fields" id="request-fields">${field('事项名称','title',title,'input')}${field('安排到哪个版本','version',existing?.version||'当前版本','input')}${field('需要开发或修改什么','request',existing?.request||'','long')}</div><p class="note">同一来源、同一版本的未完成事项会合并更新，保留此前处理记录。验收通过后的新需求另建事项。</p><button class="primary" id="submit-development">提交并保存</button>`);
  $('#submit-development').onclick=async()=>{if(busy)return;const data=Object.fromEntries([...$('#request-fields').querySelectorAll('[name]')].map(el=>[el.name,el.value]));try{const task=submitTask(d,{sourceKind:kind,sourceId:id,...data});changed();if(await save()){ $('#modal').close();taskFilter='open';taskVersion='';go('development',task.id);toast(task.id+' 已提交，可在开发进度中统一处理。');}}catch(err){toast(err.message);}};
}
function renderDevelopment(){
  const tasks=d.tasks||[],versions=[...new Set(tasks.map(t=>t.version))];
  const shown=tasks.filter(t=>!t.archived&&(!taskVersion||t.version===taskVersion)&&(taskFilter==='all'||taskFilter==='open'&&!['passed','deferred'].includes(t.status)||t.status===taskFilter));
  if(!shown.some(t=>t.id===selection))selection=shown[0]?.id||'';
  $('#workspace').innerHTML=`<div class="pagebar"><div><h2>这一版要处理的事情</h2><p>从词、语法或句子提交需求，在这里统一跟进。完成后交给你验收。</p></div></div><div class="filters"><select id="task-version" aria-label="开发版本">${option('','全部版本',taskVersion)}${versions.map(v=>option(v,v,taskVersion)).join('')}</select><select id="task-state" aria-label="开发事项状态">${option('open','未完成事项',taskFilter)}${option('all','全部事项',taskFilter)}${Object.entries(TASK_STATES).map(([k,v])=>option(k,v,taskFilter)).join('')}</select></div><div class="split"><div class="list">${shown.map(t=>`<button class="grammar-card ${t.id===selection?'active':''}" data-task="${t.id}"><span class="id">${t.id}</span><small>${e(TASK_STATES[t.status])}</small><b>${e(t.title)}</b><span class="note">${e(t.version)} · ${e(SOURCE_TYPES[t.sourceKind])}${taskOutdated(d,t)?' · 设计已变化':''}</span></button>`).join('')||'<div class="panel"><p>这里还没有符合筛选条件的事项。</p><p class="note">打开一个词、语法或句子，点击“提交开发事项”。</p></div>'}</div><div id="task-detail"></div></div>`;
  $('#task-version').onchange=ev=>{taskVersion=ev.target.value;selection='';renderDevelopment();};$('#task-state').onchange=ev=>{taskFilter=ev.target.value;selection='';renderDevelopment();};
  $$('[data-task]').forEach(b=>b.onclick=()=>navigate(()=>{selection=b.dataset.task;}));
  const t=tasks.find(t=>t.id===selection);if(!t)return;
  const stale=taskOutdated(d,t);
  $('#task-detail').innerHTML=`<article class="panel"><div class="detail-head"><div><span class="id">${t.id}</span><h2>${e(t.title)}</h2></div>${badge(t.status==='passed'?'confirmed':'draft',TASK_STATES[t.status])}</div><p class="note">${e(t.version)} · 来源：${e(SOURCE_TYPES[t.sourceKind])} ${e(sourceTitle(t.sourceKind,t.sourceId))}</p><button id="task-source" class="text-link">打开来源设计 →</button>${stale?'<div class="warning spacer">提交之后，相关设计发生了变化。此前进度保留；请核对并重新提交需求，不能直接按旧设计验收。</div>':''}<h3 class="spacer">需要处理的内容</h3><pre class="text">${e(t.request)}</pre><button id="task-resubmit" class="tiny">修改需求并重新提交</button><div class="section"><h3>进度与验收</h3><p class="note">开发完成后选“待你验收”，填写完成内容和验证结果。你验收后选“已通过”或“需要修改”。</p><div class="fields"><label>下一步状态<select id="task-next">${Object.entries(TASK_STATES).map(([k,v])=>option(k,v,t.status)).join('')}</select></label>${field('处理记录／验收反馈','task-feedback','','long')}</div><button id="task-update" class="primary spacer">保存进度</button></div><details class="section"><summary>提交时的设计${stale?'与当前设计对比':''}</summary><div class="${stale?'diff':''}"><pre class="text">${e(JSON.stringify(t.basis,null,2))}</pre>${stale?`<pre class="text">${e(JSON.stringify(taskSnapshot(d,t.sourceKind,t.sourceId),null,2))}</pre>`:''}</div></details><section class="section"><h3>处理记录</h3>${[...t.events].reverse().map(ev=>`<div class="history-entry"><b>${e(TASK_STATES[ev.status])}</b><small>${e(new Date(ev.at).toLocaleString())}</small><p>${e(ev.note||'更新进度')}</p></div>`).join('')}</section></article>`;
  $('#task-source').onclick=()=>{navigate(()=>{grammarSentence='';selection=t.sourceId;search='';offset=0;if(t.sourceKind==='sentence'){page='sentences';search=t.sourceId;filterGrammar='';filterState='all';}else if(t.sourceKind==='grammar'){page='grammar';grammarPage='definition';}else{page='words';sub=t.sourceKind==='part'?'parts':'words';}});};
  $('#task-resubmit').onclick=()=>requestDevelopment(t.sourceKind,t.sourceId,t);
  $('#task-update').onclick=async()=>{if(busy)return;try{const status=$('#task-next').value,note=$('[name="task-feedback"]').value;transitionTask(d,t,status,note);changed();if(await save()){toast(t.id+' · '+TASK_STATES[status]);}}catch(err){toast(err.message);}};
}

async function showReleases(){
  try{
    const res=await fetch('/api/releases');if(!res.ok)throw Error('版本列表读取失败');const releases=await res.json();
    modal(`<h2>历史与版本</h2><div class="subnav"><button id="release-history">保存历史</button><button class="active">命名版本</button></div><p class="note">给一个已保存的设计状态起名字并写版本说明。后续编辑不会改变这个版本；导出则用于把文件带走备份。</p>${dirty?'<div class="warning">当前有未保存编辑。请先“保存并更新”，再建立命名版本。</div>':''}<details id="new-release-form"><summary>＋ 建立命名版本</summary><div class="fields spacer">${field('版本名称','release-name','','input')}${field('这一版记录什么','release-notes','','long')}</div><button id="create-release" class="primary spacer" ${dirty?'disabled':''}>记录当前已保存版本</button></details><div class="history-list spacer">${releases.map(r=>`<div class="history-entry"><b>${e(r.name)}</b><small>${e(new Date(r.createdAt).toLocaleString())}</small><p>${e(r.notes||'未填写说明')}</p><div class="actions"><button data-release-compare="${r.id}" class="tiny">查看与比较</button><button data-release-export="${r.id}" class="tiny">导出设计</button><button data-release-restore="${r.id}" class="tiny" ${dirty||r.revision===revision?'disabled':''}>恢复到此版本</button></div></div>`).join('')||'<p class="empty">还没有命名版本。普通保存不自动建立命名版本。</p>'}</div>`);
    $('#release-history').onclick=()=>showHistory();
    $('#create-release').onclick=async()=>{if(dirty||busy)return;try{setBusy(true);await post('/api/releases',{revision,name:$('[name="release-name"]').value,notes:$('[name="release-notes"]').value});await showReleases();toast('命名版本已记录，后续修改不会覆盖它。');}catch(err){toast(err.message);}finally{setBusy(false);}};
    async function getSnapshot(r){const response=await fetch('/api/history/'+r.revision);if(!response.ok)throw Error('该版本的设计快照不可用。');return (await response.json()).design;}
    $$('[data-release-export]').forEach(b=>b.onclick=async()=>{try{const r=releases.find(r=>r.id===b.dataset.releaseExport);download('V3-version-'+r.name.replace(/[\\/:*?"<>|]/g,'-')+'.json',JSON.stringify(await getSnapshot(r),null,2));}catch(err){toast(err.message);}});
    $$('[data-release-restore]').forEach(b=>b.onclick=async()=>{if(dirty||busy)return;try{setBusy(true);const r=releases.find(r=>r.id===b.dataset.releaseRestore);acceptSaved(await post('/api/restore',{revision,target:r.revision}));await showReleases();toast('已恢复设计；已有编号和开发进度继续保留。');}catch(err){toast(err.message);}finally{setBusy(false);}});
    $$('[data-release-compare]').forEach(b=>b.onclick=async()=>{try{
      const left=releases.find(r=>r.id===b.dataset.releaseCompare),leftDoc=await getSnapshot(left);
      async function compare(rightId='current'){
        const right=releases.find(r=>r.id===rightId),rightDoc=right?await getSnapshot(right):d,rightName=right?.name||'当前编辑内容'+(dirty?'（含未保存修改）':''),diff=documentDiff(leftDoc,rightDoc);
        modal(`<h2>${e(left.name)}</h2><p class="note">${e(left.notes||'没有版本说明')}</p><label>与哪个版本比较<select id="release-target">${option('current','当前编辑内容',rightId)}${releases.filter(r=>r.id!==left.id).map(r=>option(r.id,r.name,rightId)).join('')}</select></label>${diff.map(row=>`<section class="history-change"><h3>${e(row.id)} · ${e(row.title)}</h3>${row.fields.map(f=>`<div class="change-field"><h4>${e(f.field||'整条记录')}</h4><div class="diff"><div><small>${e(left.name)}</small><pre>${e(historyValue(f.before,f.path,row.kind))}</pre></div><div><small>${e(rightName)}</small><pre>${e(historyValue(f.after,f.path,row.kind))}</pre></div></div></div>`).join('')}</section>`).join('')||'<p class="empty">两份设计内容一致。</p>'}<button id="back-releases">返回命名版本</button>`);
        $('#release-target').onchange=ev=>compare(ev.target.value).catch(err=>toast(err.message));$('#back-releases').onclick=showReleases;
      }await compare();
    }catch(err){toast(err.message);}});
  }catch(err){toast(err.message);}
}
